import re
from rich.ansi import _ansi_tokenize

re_ansi = re.compile(
    r"""
(?:\\x1b\\](.*?)\\x1b\\)|\n(?:\\x1b([0-?@-Z\\\\-_]|\\[[0-?]*[ -/]*[@-~]))\n
    """,
    re.VERBOSE,
)

def _ansi_tokenize_test(ansi_text: str):
    position = 0
    for match in re_ansi.finditer(ansi_text):
        start, end = match.span(0)
        osc, sgr = match.groups()
        print(f"Match: {ansi_text[start:end]}, osc: {osc}, sgr: {sgr}")
        if start > position:
            print(f"Plain: {ansi_text[position:start]}")
        if sgr:
            if sgr == "(":
                position = end + 1
                continue
            if sgr.endswith("m"):
                print(f"SGR: {sgr[1:-1]}")
        else:
            print(f"OSC: {osc}")
        position = end
    if position < len(ansi_text):
        print(f"Plain: {ansi_text[position:]}")

